#include <cstdio>
#include <vector>
#include <queue>
#include <functional>

int main() {
    int n;
    scanf("%d", &n);

    std::priority_queue<long long> lo;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> hi;

    for (int i = 0; i < n; ++i) {
        long long x;
        scanf("%lld", &x);
        lo.push(x);
        hi.push(lo.top()); lo.pop();
        if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }
        printf("%lld\n", lo.top());
    }
    return 0;
}
